	if [[ -n ${ZSH_VERSION:-} ]]
	then
		ARGV0=rg "$_cc_bin" ${1+"$@"}
	elif [[ "$OSTYPE" == "msys" ]] || [[ "$OSTYPE" == "cygwin" ]] || [[ "$OSTYPE" == "win32" ]]
	then
		ARGV0=rg "$_cc_bin" ${1+"$@"}
	else
		(
			exec -a rg "$_cc_bin" ${1+"$@"}
		)
	fi
}
